using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
public static class RestoreSrpPineShaders {
 public static object Run(){if(EditorApplication.isPlaying||EditorApplication.isCompiling)throw new Exception("Edit Mode required");var rows=File.ReadAllLines("Recovery/DrawCalls_20261107/InstalledMaterialShaders.tsv").Skip(1).Where(s=>!String.IsNullOrWhiteSpace(s));var changes=new Dictionary<Material,Shader>();var report=new System.Text.StringBuilder("material\tfrom\tto\n");foreach(var row in rows){var p=row.Split('\t');var m=AssetDatabase.LoadAssetAtPath<Material>(p[0]);var original=AssetDatabase.LoadAssetAtPath<Shader>(p[1]);var instanced=AssetDatabase.LoadAssetAtPath<Shader>(p[2]);if(!m||!original||!instanced||m.shader!=instanced)throw new Exception("Unexpected shader binding: "+p[0]);changes[m]=original;report.AppendLine(p[0]+"\t"+p[2]+"\t"+p[1]);}if(changes.Count!=10)throw new Exception("Expected10 material bindings");Directory.CreateDirectory("Recovery/PresentationDiagnosis_20261107");File.WriteAllText("Recovery/PresentationDiagnosis_20261107/RestoredSrpShaders.tsv",report.ToString());Undo.RecordObjects(changes.Keys.ToArray(),"Restore faster SRP pine shader path");foreach(var p in changes){p.Key.shader=p.Value;EditorUtility.SetDirty(p.Key);AssetDatabase.SaveAssetIfDirty(p.Key);}return "Restored10 pine material shader bindings to original SRP-compatible shaders; textures, wind, meshes and all other material settings retained";}
}
